while true; do
  find /download -mindepth 1 -mmin +15 -type f -exec fuser -s {} \; -o -exec rm -rf {} +;
  sleep 600;
done &
exec /app/media-roller

server {
    listen 80;
    server_name _;
    root /var/www/html;
    index index.html;
    real_ip_header X-Forwarded-For;
    set_real_ip_from 10.42.0.0/16;
    set_real_ip_from 192.168.42.0/24;
    location / {
        try_files $uri $uri/ =404;
    }
}
